solution.solution.cpp:
#include <cctype>
#include <string>
#include <vector>

class TextFilter
{
public:
    explicit TextFilter(const std::string& text)
    {
        std::string term;
        auto finish = [&] {
            const auto a{ term.find_first_not_of(' ') };
            if (a != std::string::npos)
            {
                std::string t{ term.substr(a, term.find_last_not_of(' ') - a + 1) };
                if (t != "-") { m_terms.push_back(t); if (t[0] != '-') ++m_inclusions; }
            }
            term.clear();
        };
        for (char c : text) { if (c == ',') finish(); else term += c; }
        finish();
    }

    bool pass(const std::string& line) const
    {
        if (m_terms.empty()) return true;
        const std::string hay{ lower(line) };
        for (const std::string& t : m_terms)
        {
            const bool exclude{ t[0] == '-' };
            const std::string needle{ lower(exclude ? t.substr(1) : t) };
            if (hay.find(needle) != std::string::npos) return !exclude;
        }
        return m_inclusions == 0;
    }

private:
    static std::string lower(std::string s)
    {
        for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        return s;
    }
    std::vector<std::string> m_terms;
    int m_inclusions{ 0 };
};

unitTests:
TEST("empty passes everything") { CHECK(TextFilter("").pass("anything")); CHECK(TextFilter(" , ,").pass("x")); }
TEST("exclusion first") { const TextFilter f{ "-missing,texture" }; CHECK(f.pass("Texture loaded")); CHECK(!f.pass("texture MISSING")); CHECK(!f.pass("shader")); }
TEST("order matters") { CHECK(TextFilter("texture,-missing").pass("texture missing")); }
TEST("only exclusions") { const TextFilter f{ "-vsync" }; CHECK(f.pass("frame done")); CHECK(!f.pass("VSync on")); }
TEST("either inclusion") { const TextFilter f{ " texture , shader " }; CHECK(f.pass("shader compiled")); CHECK(f.pass("texture")); CHECK(!f.pass("audio")); }
TEST("a lone minus is ignored") { CHECK(TextFilter("-").pass("x")); CHECK(!TextFilter("-,abc").pass("x")); }

